+function notify(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('on');setTimeout(()=>el.classList.remove('on'),1700)}function log(t){document.querySelector('#event').textContent=t;document.querySelector('#status').textContent=t}function setBall(){ball.x=me.x+.024;ball.y=me.y;ball.owner=0}function passBall(){if(!gameOn)return;let target=mates.filter(p=>p!==me).sort((a,b)=>Math.hypot(a.x-me.x,a.y-me.y)-Math.hypot(b.x-me.x,b.y-me.y))[0];ball={x:me.x,y:me.y,vx:(target.x-me.x)*.055,vy:(target.y-me.y)*.055,owner:-1};setTimeout(()=>{ball.x=target.x;ball.y=target.y;ball.vx=0;ball.vy=0;ball.owner=0;log(roster[selected].name+' finds the pass. Move into space!')},450);log('Pass threaded into space…')}
+function shoot(){if(!gameOn)return;let distance=Math.abs(me.x-.97),success=me.x>.69&&Math.random()<(.5+(roster[selected].stats.SHO||80)/250);ball={x:me.x,y:me.y,vx:.095,vy:(.5-me.y)*.025,owner:-1};log(success?'SHOT — THE KEEPER IS BEATEN!':'A fierce strike — the keeper makes the save!');if(success){score[0]++;document.querySelector('#score').textContent=score[0]+' — '+score[1];document.querySelector('#overlay').classList.add('show');setTimeout(()=>document.querySelector('#overlay').classList.remove('show'),1500);setTimeout(()=>{me.x=.43;me.y=.5;setBall()},600)}setTimeout(()=>{if(ball.x>.98||!success){ball.x=.5;ball.y=.5;ball.vx=ball.vy=0;ball.owner=0}},500)}
